def old_bridge(row, b, c, review, assessment, delivery, evidence, predecessors, action, new_plan=None):
    review_gate = ReviewGate(reference(review['id'], review['version']), Cycle(review['delivery_cycle'], review['review_cycle']), review['artifact_revision'], ReviewOutcome.ACCEPTED if review['verdict'] == 1 else ReviewOutcome.REJECTED, self.review_complete(review), review['reviewer_id'] == row['owner_id']) if review else None
    release_gate, rollback_gate = (None, None)
    if action == Action.DELIVER and assessment:
        release_gate = ReleaseGate(reference(assessment['id'], assessment['version']), assessment['delivery_cycle'], assessment['schedule_version'], assessment['status'] == 2, bool(assessment['review_evidence']), assessment['status'] == 2, assessment['created_by'] == assessment['reviewed_by'])
    if action == Action.ROLLBACK and assessment:
        rollback_gate = RollbackGate(reference(assessment['id'], b['rollback_plan_version']), assessment['delivery_cycle'], assessment['status'] == 2, bool(delivery and delivery[0]['assessment_id'] == assessment['id'] and (delivery[0]['rollback_plan_version'] == b['rollback_plan_version'])))
    context = TransitionContext(True, frozenset((ROLE_TO_DOMAIN[r] for r in roles(c.membership['roles_mask']))), c.actor_id == row['owner_id'], tuple((STATE_TO_DOMAIN[t['state']] for t in predecessors)), Cycle(row['delivery_cycle'], row['review_cycle']), row['schedule_version'], row['artifact_revision'], reference(row['latest_review_id'], 1) if row['latest_review_id'] else None, reference(row['approved_review_id'], 1) if row['approved_review_id'] else None, review_gate, release_gate, rollback_gate, 'new-plan' if new_plan else None)
    commands = {Action.START: lambda: StartDevelopment(), Action.BLOCK: lambda: RecordBlock(b['reason'], STAGE_TO_DOMAIN[b['responsibility_stage']], evidence), Action.UNBLOCK: lambda: ResolveBlock(b['basis'], evidence), Action.SUBMIT_REVIEW: lambda: SubmitForReview(b['artifact_revision'], evidence), Action.APPROVE_REVIEW: lambda: AcceptReview(reference(b['review_id'], b['review_version'])), Action.REJECT_REVIEW: lambda: ReturnForChanges(reference(b['review_id'], b['review_version']), b['reason']), Action.DELIVER: lambda: ApproveDelivery(reference(b['assessment_id'], b['assessment_version']), b['release_version'], b['reason'], evidence), Action.ROLLBACK: lambda: RecordRollback(b['reason'], b['impact'], b['target_version'], reference(b['assessment_id'], b['rollback_plan_version']), evidence), Action.REWORK: lambda: AuthorizeRework('new-plan', b['reason'], evidence)}
    position = TaskPosition(STATE_TO_DOMAIN[row['state']], STATE_TO_DOMAIN[row['blocked_from_state']] if row['blocked_from_state'] else None)
    decision = decide(position, commands[action](), context)
    return decision
